SET 'execution.runtime-mode'='batch';
SET 'table.dml-sync'='true';
CREATE TEMPORARY VIEW a_source AS SELECT * FROM (VALUES (CAST(9007199254740993 AS BIGINT),CAST(12.3400 AS DECIMAL(24,4)),'  水🌊  ','x'),(CAST(9007199254740993 AS BIGINT),CAST(12.3400 AS DECIMAL(24,4)),'  水🌊  ','x'),(CAST(2 AS BIGINT),CAST(0.0100 AS DECIMAL(24,4)),'  O''Reilly  ','x'),(CAST(NULL AS BIGINT),CAST(NULL AS DECIMAL(24,4)),CAST(NULL AS STRING),CAST(NULL AS STRING))) AS t(id,amount,name,junk);
CREATE TEMPORARY VIEW c_source AS SELECT * FROM (VALUES ('MiXeD',1,'first'),('MiXeD',1,'first'),('mixed',1,'second'),(CAST(NULL AS STRING),3,'null-first'),(CAST(NULL AS STRING),3,'null-first'),(CAST(NULL AS STRING),4,'null-second'),('H',5,CAST(NULL AS STRING))) AS t(`group`,id,payload);
CREATE TEMPORARY VIEW d_source AS SELECT * FROM (VALUES ('Ab',CAST(1 AS BIGINT)),('Ab',CAST(1 AS BIGINT)),('ab',CAST(1 AS BIGINT)),(CAST(NULL AS STRING),CAST(2 AS BIGINT)),(CAST(NULL AS STRING),CAST(2 AS BIGINT)),('Other',CAST(3 AS BIGINT))) AS t(id,n);
CREATE TEMPORARY TABLE `a_out` (`id` BIGINT, `amount` DECIMAL(24,4), `名称` STRING, `bucket` STRING, `marker` STRING, `trace` STRING, `which` STRING, `value` STRING) WITH ('connector'='filesystem','path'='file:///tmp/datahub-control-3f4f1fe51e87-flink-dedup-duplicate/data/a_out','format'='json');
CREATE TEMPORARY TABLE `c_out` (`group` STRING, `id` INT, `payload` STRING) WITH ('connector'='filesystem','path'='file:///tmp/datahub-control-3f4f1fe51e87-flink-dedup-duplicate/data/c_out','format'='json');
CREATE TEMPORARY TABLE `d_out` (`id` STRING, `n` BIGINT) WITH ('connector'='filesystem','path'='file:///tmp/datahub-control-3f4f1fe51e87-flink-dedup-duplicate/data/d_out','format'='json');
INSERT INTO `c_out` (`group`, `id`, `payload`) SELECT `group`, `id`, `payload` FROM (SELECT `group`, `id`, `payload` FROM (SELECT dh_dedup_input.*, ROW_NUMBER() OVER (PARTITION BY LOWER(`group`) ORDER BY `id` ASC NULLS LAST) AS `dh_dedup_row` FROM (SELECT `group`, `id`, `payload` FROM (SELECT dh_order_input.*, COUNT(*) OVER (PARTITION BY `id`) AS `dh_unique_count` FROM (SELECT DISTINCT `group`, `id`, `payload` FROM (SELECT `group` AS `group`, `id` AS `id`, `payload` AS `payload` FROM (SELECT `group`, `id`, `payload` FROM `c_source`) dh_stage) dh_dedup_distinct) dh_order_input) dh_order_checked WHERE CASE WHEN `dh_unique_count` = 1 THEN TRUE ELSE CAST(CONCAT('唯一排序字段存在重复值: ', COALESCE(CAST(`dh_unique_count` AS STRING), '')) AS BIGINT) = 0 END) dh_dedup_input) dh_dedup_first WHERE `dh_dedup_row` = 1) dh_output;